{
  "index_test": "whole-animal-in-vivo",
  "index_test_evidence": "Neuroscientists commonly employ in vivo animal models, aimed to simulate physiological, genetic, or anatomical features observed in humans (as is the case with studies of disease) or replicate natural situations under controlled laboratory conditions (van der Staay, 2006; Maximino and van der Staay, 2019).",
  "decision": "exclude",
  "reason": "The study discusses the importance of animal models and experimental rigor in behavioral neuroscience but does not report any quantitative measure of agreement between animal results and human clinical results. It focuses on improving reproducibility and research quality rather than comparing predictive accuracy."
}
